-- GoSnack: esquema PostgreSQL compatible con Supabase.
-- Opción recomendada: usar este archivo en SQL Editor y luego configurar DATABASE_URL.
BEGIN;
CREATE TABLE IF NOT EXISTS roles (id_rol integer PRIMARY KEY, nombre varchar(50) UNIQUE NOT NULL, descripcion text, activo boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS categorias (id_categoria integer PRIMARY KEY, nombre varchar(100) UNIQUE NOT NULL, descripcion text, icono_url varchar(255), orden integer NOT NULL DEFAULT 0, activo boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS usuarios (id_usuario integer PRIMARY KEY, email varchar(255) UNIQUE NOT NULL, password_hash varchar(255) NOT NULL, nombre_completo varchar(255) NOT NULL, codigo_estudiante varchar(20) UNIQUE, telefono varchar(20), id_rol integer NOT NULL REFERENCES roles(id_rol), verificado boolean NOT NULL DEFAULT false, activo boolean NOT NULL DEFAULT true, fecha_registro timestamptz NOT NULL DEFAULT now(), ultimo_acceso timestamptz);
CREATE TABLE IF NOT EXISTS productos (id_producto integer PRIMARY KEY, nombre varchar(255) NOT NULL, descripcion text, id_categoria integer NOT NULL REFERENCES categorias(id_categoria), precio_base numeric(10,2) NOT NULL, imagen_url varchar(255), destacado boolean NOT NULL DEFAULT false, activo boolean NOT NULL DEFAULT true, fecha_creacion timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inventario (id_inventario integer PRIMARY KEY, id_producto integer UNIQUE NOT NULL REFERENCES productos(id_producto) ON DELETE CASCADE, stock_actual integer NOT NULL DEFAULT 0, stock_minimo integer NOT NULL DEFAULT 5, stock_maximo integer NOT NULL DEFAULT 100, ultima_actualizacion timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ofertas (id_oferta integer PRIMARY KEY, id_producto integer NOT NULL REFERENCES productos(id_producto) ON DELETE CASCADE, tipo_descuento varchar(20) NOT NULL, valor_descuento numeric(10,2) NOT NULL, descripcion varchar(255), fecha_inicio timestamptz NOT NULL, fecha_fin timestamptz NOT NULL, limite_cantidad integer, cantidad_vendida integer NOT NULL DEFAULT 0, activo boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS estados_pedido (id_estado integer PRIMARY KEY, nombre varchar(50) UNIQUE NOT NULL, descripcion text, color_hex varchar(7) NOT NULL DEFAULT '#CCCCCC');
CREATE TABLE IF NOT EXISTS pedidos (id_pedido integer PRIMARY KEY, codigo_pedido varchar(25) UNIQUE NOT NULL, id_usuario integer NOT NULL REFERENCES usuarios(id_usuario), id_estado integer NOT NULL REFERENCES estados_pedido(id_estado), subtotal numeric(10,2) NOT NULL, descuento numeric(10,2) NOT NULL DEFAULT 0, total numeric(10,2) NOT NULL, notas_especiales text, fecha_pedido timestamptz NOT NULL DEFAULT now(), fecha_estimada_retiro timestamptz, cancelado boolean NOT NULL DEFAULT false, fecha_cancelacion timestamptz, motivo_cancelacion text);
CREATE TABLE IF NOT EXISTS detalle_pedido (id_detalle integer PRIMARY KEY, id_pedido integer NOT NULL REFERENCES pedidos(id_pedido) ON DELETE CASCADE, id_producto integer NOT NULL REFERENCES productos(id_producto), id_oferta integer REFERENCES ofertas(id_oferta) ON DELETE SET NULL, cantidad integer NOT NULL, precio_unitario numeric(10,2) NOT NULL, descuento_aplicado numeric(10,2) NOT NULL DEFAULT 0, subtotal numeric(10,2) NOT NULL, notas text);
CREATE TABLE IF NOT EXISTS qr_kiosko (id_qr integer PRIMARY KEY, banco varchar(100) NOT NULL, titular varchar(255) NOT NULL, numero_cuenta varchar(50), imagen_qr_url varchar(255) NOT NULL, activo boolean NOT NULL DEFAULT true, fecha_registro timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transacciones (id_transaccion integer PRIMARY KEY, id_pedido integer UNIQUE NOT NULL REFERENCES pedidos(id_pedido), id_qr_usado integer NOT NULL REFERENCES qr_kiosko(id_qr), monto numeric(10,2) NOT NULL, estado varchar(30) NOT NULL DEFAULT 'pendiente_validacion', fecha_transaccion timestamptz NOT NULL DEFAULT now(), validado_por integer REFERENCES usuarios(id_usuario) ON DELETE SET NULL, fecha_validacion timestamptz, notas_validacion text);
CREATE TABLE IF NOT EXISTS comprobantes (id_comprobante integer PRIMARY KEY, id_transaccion integer NOT NULL REFERENCES transacciones(id_transaccion) ON DELETE CASCADE, imagen_url varchar(255) NOT NULL, monto_detectado numeric(10,2), hash_imagen varchar(64) UNIQUE, fecha_subida timestamptz NOT NULL DEFAULT now(), validado boolean NOT NULL DEFAULT false);

-- Datos: usuarios.rol
-- Datos: usuarios.usuario
-- Datos: catalogo.categoria
-- Datos: catalogo.producto
-- Datos: catalogo.inventario
-- Datos: catalogo.oferta
-- Datos: pedidos.estadopedido
-- Datos: pedidos.pedido
-- Datos: pedidos.detallepedido
-- Datos: pagos.qrkiosko
-- Datos: pagos.transaccion
-- Datos: pagos.comprobante
COMMIT;
